    localparam logic STATE_WALK_RIGHT = 1'b1;

    logic state, next_state;

    // Avoid X-propagation before the first async reset event.
    initial begin
        state = STATE_WALK_LEFT;
    end

    // Moore next-state and outputs combinational logic
    always @(*) begin
        // Default: stay in current direction
        next_state = state;

        // If bumped on the left, walk right
        if (bump_left) begin
            next_state = STATE_WALK_RIGHT;
        end
        // Else if bumped on the right, walk left
        else if (bump_right) begin
            next_state = STATE_WALK_LEFT;
        end
        // If both are 1, bump_left has priority -> walk right

        // Moore outputs based on current state
        walk_left  = (state == STATE_WALK_LEFT);
        walk_right = (state == STATE_WALK_RIGHT);
    end

    // State register with asynchronous positive-edge reset
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= STATE_WALK_LEFT;
        end else begin
            state <= next_state;
        end
    end"
  }
}

